// Минимальный клиент Appium (W3C REST через fetch, Node 22, без зависимостей) для нативного приложения Banci на реальном iPhone.
// Личные значения (UDID, Team ID, bundle id WDA) — ТОЛЬКО из переменных окружения, см. README.md.
import { writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
export const APP_BUNDLE_ID = process.env.BANCI_BUNDLE_ID || 'com.julius.banci';
/** Названия кнопки отмены в системных окнах iOS (зависят от языка телефона). */
export const CANCEL = /^(ביטול|Cancel|Отменить|Отмена|Annuler|Abbrechen)$/i;
const APPIUM = (process.env.APPIUM_URL || 'http://localhost:4723').replace(/\/$/, '');

function need(name) {
  const v = process.env[name];
  if (!v) throw new Error(`Нет переменной окружения ${name} — значение взять из ~/.qa-tester/devices.md (см. .qa/e2e-app/README.md)`);
  return v;
}

export function capabilities() {
  const caps = {
    platformName: 'iOS',
    'appium:automationName': 'XCUITest',
    'appium:bundleId': APP_BUNDLE_ID,
    'appium:udid': need('BANCI_UDID'),
    'appium:updatedWDABundleId': need('WDA_BUNDLE_ID'),
    'appium:xcodeOrgId': need('XCODE_ORG_ID'),
    'appium:xcodeSigningId': process.env.XCODE_SIGNING_ID || 'Apple Development',
    'appium:noReset': true, // не трогаем данные и вход приложения
    'appium:newCommandTimeout': 3600,
    'appium:wdaLaunchTimeout': 240000,
  };
  if (process.env.WDA_DERIVED_DATA) {
    caps['appium:usePrebuiltWDA'] = true;
    caps['appium:derivedDataPath'] = process.env.WDA_DERIVED_DATA;
  }
  return caps;
}

async function http(method, url, body) {
  const res = await fetch(url, {
    method,
    headers: { 'Content-Type': 'application/json' },
    body: body === undefined ? undefined : JSON.stringify(body),
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) {
    const err = new Error(`${method} ${url.replace(APPIUM, '')} → ${res.status} ${json?.value?.error || ''}: ${json?.value?.message?.split('\n')[0] || ''}`);
    err.code = json?.value?.error;
    throw err;
  }
  return json.value;
}

/** Предикат iOS: точное совпадение name/label. */
const q = (s) => `"${String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;
export const by = {
  exact: (text, type) => `(name == ${q(text)} OR label == ${q(text)})${type ? ` AND type == ${q('XCUIElementType' + type)}` : ''}`,
  begins: (text, type) => `(name BEGINSWITH ${q(text)} OR label BEGINSWITH ${q(text)})${type ? ` AND type == ${q('XCUIElementType' + type)}` : ''}`,
  contains: (text, type) => `(name CONTAINS ${q(text)} OR label CONTAINS ${q(text)})${type ? ` AND type == ${q('XCUIElementType' + type)}` : ''}`,
};

export class App {
  constructor(sessionId) {
    this.id = sessionId;
    this.base = `${APPIUM}/session/${sessionId}`;
  }

  static async start() {
    const v = await http('POST', `${APPIUM}/session`, { capabilities: { alwaysMatch: capabilities() } });
    const app = new App(v.sessionId);
    await app.activate();
    return app;
  }

  /** Сессия ещё отвечает? (в авиарежиме связь Appium ↔ WDA рвётся: «socket hang up»). */
  async alive() {
    try { await this.windowRect(); return true; } catch { return false; }
  }

  /**
   * Новая сессия Appium вместо потерянной — БЕЗ перезапуска приложения (мониторинг продолжается).
   * Объект App тот же (меняется только id/base), поэтому run.mjs закроет уже новую сессию.
   * forceAppLaunch:false — приложение не перезапускается; shouldTerminateApp:false — не закрывается при выходе из сессии.
   */
  async reconnect() {
    const caps = { ...capabilities(), 'appium:forceAppLaunch': false, 'appium:shouldTerminateApp': false };
    const v = await http('POST', `${APPIUM}/session`, { capabilities: { alwaysMatch: caps } });
    this.id = v.sessionId;
    this.base = `${APPIUM}/session/${v.sessionId}`;
    if ((await this.appState()) !== 4) await this.activate(); // activateApp выводит на передний план, не перезапускает
  }

  async quit() {
    await http('DELETE', this.base).catch(() => {});
  }

  exec(script, args = {}) {
    return http('POST', `${this.base}/execute/sync`, { script, args: [args] });
  }

  /** Перезапуск приложения — чистое начальное состояние без сброса данных. */
  async restart() {
    await this.exec('mobile: terminateApp', { bundleId: APP_BUNDLE_ID }).catch(() => {});
    await this.activate();
  }

  activate() {
    return this.exec('mobile: activateApp', { bundleId: APP_BUNDLE_ID });
  }

  windowRect() {
    return http('GET', `${this.base}/window/rect`);
  }

  async findAll(predicate) {
    const els = await http('POST', `${this.base}/elements`, { using: '-ios predicate string', value: `(${predicate}) AND visible == 1` });
    return els.map((e) => new El(this, Object.values(e)[0], predicate));
  }

  /** Ждёт видимый элемент (поллинг результата, без фиксированных пауз-ожиданий). */
  async waitFor(predicate, { timeout = 15000, what } = {}) {
    const end = Date.now() + timeout;
    let last;
    while (Date.now() < end) {
      try {
        const els = await this.findAll(predicate);
        if (els.length) return els[0];
      } catch (e) { last = e; }
      await new Promise((r) => setTimeout(r, 300)); // интервал опроса, не ожидание результата
    }
    throw new Error(`Не найден за ${timeout} мс: ${what || predicate}${last ? ` (${last.message})` : ''}`);
  }

  async waitGone(predicate, { timeout = 10000, what } = {}) {
    const end = Date.now() + timeout;
    while (Date.now() < end) {
      if (!(await this.findAll(predicate)).length) return;
      await new Promise((r) => setTimeout(r, 300));
    }
    throw new Error(`Не исчез за ${timeout} мс: ${what || predicate}`);
  }

  async exists(predicate) {
    return (await this.findAll(predicate)).length > 0;
  }

  async tap(predicate, opts) {
    const el = await this.waitFor(predicate, opts);
    await el.click();
    return el;
  }

  /** Прокрутка вверх/вниз жестом, пока элемент не станет видимым. */
  async scrollTo(predicate, { max = 8, direction = 'down', what } = {}) {
    for (let i = 0; i <= max; i++) {
      const els = await this.findAll(predicate);
      if (els.length) return els[0];
      await this.exec('mobile: swipe', { direction: direction === 'down' ? 'up' : 'down' });
    }
    throw new Error(`Не найден после прокрутки: ${what || predicate}`);
  }

  /** Системное окно iOS (UIAlert), если оно есть: { title, buttons[] }. */
  async alert() {
    try {
      const text = await http('GET', `${this.base}/alert/text`);
      const buttons = await this.exec('mobile: alert', { action: 'getButtons' }).catch(() => []);
      return { text, buttons };
    } catch (e) {
      if (e.code === 'no such alert') return null;
      throw e;
    }
  }

  async waitAlert({ timeout = 10000 } = {}) {
    const end = Date.now() + timeout;
    while (Date.now() < end) {
      const a = await this.alert();
      if (a) return a;
      await new Promise((r) => setTimeout(r, 300));
    }
    throw new Error(`Системное окно iOS не появилось за ${timeout} мс`);
  }

  /** Закрыть системное окно кнопкой отмены по названию. Нет такой кнопки — окно не трогаем. */
  async cancelAlert() {
    const a = await this.alert();
    if (!a) return null;
    const label = (a.buttons || []).find((b) => CANCEL.test(String(b).trim()));
    if (!label) throw new Error(`В системном окне нет кнопки отмены: ${JSON.stringify(a)}`);
    await this.exec('mobile: alert', { action: 'dismiss', buttonLabel: label });
    return { ...a, pressed: label };
  }

  /** Состояние приложения: 4 = на переднем плане. */
  appState(bundleId = APP_BUNDLE_ID) {
    return this.exec('mobile: queryAppState', { bundleId });
  }

  async screenshot(name) {
    const dir = path.join(ROOT, 'results');
    await mkdir(dir, { recursive: true });
    const file = path.join(dir, `${new Date().toISOString().slice(0, 10)}-${name}.png`);
    const b64 = await http('GET', `${this.base}/screenshot`);
    await writeFile(file, Buffer.from(b64, 'base64'));
    return file;
  }
}

export class El {
  constructor(app, id, predicate) {
    this.app = app;
    this.id = id;
    this.predicate = predicate;
    this.base = `${app.base}/element/${id}`;
  }
  click() { return http('POST', `${this.base}/click`, {}); }
  attr(name) { return http('GET', `${this.base}/attribute/${name}`); }
  rect() { return http('GET', `${this.base}/rect`); }
  async enabled() { return String(await this.attr('enabled')) === 'true'; }
  /** Ввод текста в поле (W3C element value). */
  type(text) { return http('POST', `${this.base}/value`, { text: String(text) }); }
}

/** Значение доступности чекбокса → true/false/null. «unchecked» проверяется первым (содержит «checked»). */
export function checkedFromValue(value) {
  const v = String(value ?? '').toLowerCase();
  if (/unchecked|not checked|לא מסומן|לא נבחר/.test(v)) return false;
  if (/checked|מסומן|נבחר/.test(v) || v === '1') return true;
  if (v === '0') return false;
  return null;
}

export function assert(cond, message) {
  if (!cond) throw new Error(`Проверка не прошла: ${message}`);
}

/** Пропустить тест с понятной причиной (ручное предусловие не выставлено). run.mjs считает его «skipped», не «failed». */
export function skip(reason) {
  const e = new Error(`ПРОПУЩЕН: ${reason}`);
  e.skip = true;
  throw e;
}
